// Extrair dados do request body
const body = $json.body;

const uf = (body.uf || '').toUpperCase().trim();
const municipio = (body.municipio || '').trim();
const meio_transporte = body.meio_transporte || 'Não informado';
const acompanhantes = body.acompanhantes || 'Não informado';
const periodo = body.periodo || 'Não informado';
const objetivo = body.objetivo || 'Não informado';

if (!uf || !municipio) {
  return [{ json: { erro: true, mensagem: 'UF e município são obrigatórios.' } }];
}

return [{
  json: {
    uf,
    municipio,
    meio_transporte,
    acompanhantes,
    periodo,
    objetivo,
    erro: false
  }
}];

const items = $input.all();
const uf = $('Validar Input').item.json.uf;
const municipio = $('Validar Input').item.json.municipio;

const detalhes = {};
let totalGeral = 0;

for (const item of items) {
  const evento = item.json.evento;
  const total = parseInt(item.json.total_ocorrencias) || 0;
  detalhes[evento] = total;
  totalGeral += total;
}

return [{
  json: {
    contexto_destino: {
      uf,
      municipio,
      total_geral: totalGeral,
      detalhes_eventos: detalhes
    }
  }
}];

const items = $input.all();
const uf = $('Validar Input').item.json.uf;
const municipioAlt = $('Query Municipio Mais Seguro').item.json.municipio;
const contextDestino = $('Formatar Dados Destino').item.json.contexto_destino;
const userInput = $('Validar Input').item.json;

const detalhesAlt = {};
let totalGeralAlt = 0;

for (const item of items) {
  const evento = item.json.evento;
  const total = parseInt(item.json.total_ocorrencias) || 0;
  detalhesAlt[evento] = total;
  totalGeralAlt += total;
}

const sugestaoAlternativa = {
  uf,
  municipio: municipioAlt,
  total_geral: totalGeralAlt,
  detalhes_eventos: detalhesAlt
};

// Montar payload para LLM
const payload = {
  contexto_destino: contextDestino,
  sugestao_alternativa: sugestaoAlternativa,
  contexto_usuario: {
    meio_transporte: userInput.meio_transporte,
    acompanhantes: userInput.acompanhantes,
    periodo: userInput.periodo,
    objetivo: userInput.objetivo
  }
};

return [{ json: { payload } }];

const payload = $json.payload;

const systemPrompt = `Você é um assistente especializado em segurança pública brasileira. 
Sua função é analisar dados criminais de municípios brasileiros e fornecer 
recomendações personalizadas de segurança para viajantes e moradores.

Sempre responda em português brasileiro.
Seja objetivo, prático e empático.
Baseie suas recomendações exclusivamente nos dados fornecidos.
Não invente dados ou estatísticas.`;

const userPrompt = `Com base nos dados criminais abaixo, forneça uma análise personalizada de segurança.

## DADOS DO MUNICÍPIO DE DESTINO (${payload.contexto_destino.municipio}/${payload.contexto_destino.uf}):
- Total de ocorrências: ${payload.contexto_destino.total_geral}
- Detalhes por tipo de crime:
${Object.entries(payload.contexto_destino.detalhes_eventos).map(([evento, total]) => `  - ${evento}: ${total}`).join('\n')}

## SUGESTÃO ALTERNATIVA MAIS SEGURA (${payload.sugestao_alternativa.municipio}/${payload.sugestao_alternativa.uf}):
- Total de ocorrências: ${payload.sugestao_alternativa.total_geral}
- Detalhes por tipo de crime:
${Object.entries(payload.sugestao_alternativa.detalhes_eventos).map(([evento, total]) => `  - ${evento}: ${total}`).join('\n')}

## CONTEXTO DO USUÁRIO:
- Meio de transporte: ${payload.contexto_usuario.meio_transporte}
- Acompanhantes: ${payload.contexto_usuario.acompanhantes}
- Período da viagem: ${payload.contexto_usuario.periodo}
- Objetivo: ${payload.contexto_usuario.objetivo}

## INSTRUÇÕES:
1. Faça uma análise comparativa entre o município de destino e a alternativa mais segura
2. Destaque os principais riscos do destino escolhido
3. Dê recomendações de segurança personalizadas considerando o meio de transporte, acompanhantes e período
4. Sugira precauções específicas para os crimes mais frequentes na região
5. Se apropriado, recomende a alternativa mais segura com justificativa baseada nos dados`;

return [{
  json: {
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    payload: payload
  }
}];

const response = $json;
const payload = $('Montar Payload LLM').item.json.payload;

let analise = '';
let model = '';
let tokens_used = 0;

try {
  analise = response.choices[0].message.content;
  model = response.model || 'llama-3.1-70b-versatile';
  tokens_used = response.usage ? response.usage.total_tokens : 0;
} catch(e) {
  analise = 'Não foi possível gerar a análise. Tente novamente.';
}

return [{
  json: {
    success: true,
    analise: analise,
    modelo: model,
    tokens_utilizados: tokens_used,
    dados: {
      destino: payload.contexto_destino,
      alternativa: payload.sugestao_alternativa,
      contexto_usuario: payload.contexto_usuario
    }
  }
}];
